from defusedxml import minidom
import glob

path = "unpacked/word/document.xml"
dom = minidom.parse(path)
paras = dom.getElementsByTagName("w:p")
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def local(tag):
    return tag.split("}")[-1] if "}" in tag else tag

for i, p in enumerate(paras):
    style = ""
    pPr = p.getElementsByTagName("w:pPr")
    if pPr:
        pStyle = pPr[0].getElementsByTagName("w:pStyle")
        if pStyle:
            style = pStyle[0].getAttribute("w:val")
    texts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.getElementsByTagName("w:t"):
            if t.firstChild:
                texts.append(t.firstChild.nodeValue)
    text = "".join(texts)
    if style:
        print(f"[{i}] style={style} text={text!r}")
    else:
        print(f"[{i}] style=(none) text={text[:60]!r}")

