    print(f"--- Para {i} ---")
    print("text:", "".join(texts)[:80])
    print("rPr count:", len(rPrs))
    print("rPrs:", rPrs[:3])
    print()

from defusedxml import minidom

dom = minidom.parse("unpacked/word/document.xml")
paras = dom.getElementsByTagName("w:p")

def para_text(p):
    parts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.getElementsByTagName("w:t"):
            if t.firstChild:
                parts.append(t.firstChild.nodeValue)
    return "".join(parts)

for i, p in enumerate(paras):
    text = para_text(p).strip()
    if not text:
        continue
    has_letter = any(c.isalpha() for c in text)
    is_upper = text == text.upper()
