        print(f"[{i}] ALL-CAPS: {text!r}")

import os, sys
sys.path.insert(0, os.path.abspath(".codex/skills/docx"))
from scripts.utilities import XMLEditor

editor = XMLEditor("unpacked/word/document.xml")
dom = editor.dom
paras = dom.getElementsByTagName("w:p")

def para_text(p):
    parts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.getElementsByTagName("w:t"):
            if t.firstChild:
                parts.append(t.firstChild.nodeValue)
    return "".join(parts)

def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    if not any(c.isalpha() for c in text):
        return False
    return text == text.upper()

headlines = 0
for p in paras:
    if not is_headline(p):
        continue
    for r in p.getElementsByTagName("w:r"):
        rPrs = r.getElementsByTagName("w:rPr")
        if rPrs:
            rPr = rPrs[0]
        else:
            rPr = dom.createElement("w:rPr")
            r.insertBefore(rPr, r.firstChild)
        if rPr.getElementsByTagName("w:u"):
            continue
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        rPr.appendChild(u)
    headlines += 1

print("Headline paragraphs underlined:", headlines)
editor.save()

